files = []
def walk(path):
    for entry in repo.list(path):
        if entry.endswith("/"):
            walk(path + entry)
        else:
            files.append(path + entry)

walk("src/")
walk("docs/")

contents = {}
for f in files:
    c = repo.read(f, missing_ok=True)
    contents[f] = c if c != None else "<binary or unreadable>"

return {
    "files": files,
    "contents": contents,
}
